/* GERADO POR scripts/gerar-fonte-python.mjs — NÃO EDITAR À MÃO.
   Origem: laboratorio/src/balcao/{__init__.py,corpus.py,didactico.py}.
   Corre `npm run gerar-fonte` depois de mexer no runtime. */

function decodificar(b64: string): string {
  return new TextDecoder().decode(Uint8Array.from(atob(b64), (c) => c.charCodeAt(0)));
}

